$(document).ready(function($)
{
    window.__mustOpenIframe = function(target)
    {
        if($(target).data('openiframe'))
            return true;

        return false;
    }

    window.__getDataTableSelectedIds = function(target, datatable)
    {
        let idColumnIndex = window.__getIdColumnIndex(target, datatable);
        let selectedRows = datatable.rows( { selected: true } );
        var ids = selectedRows.data().pluck(idColumnIndex).toArray();

        return ids;
    }

    window.__openIframe = function(target)
    {
        let table = window.__getTable(target);
        let tableId = $(table).data('realid');

        let datatable = table.DataTable();

        let ids = window.__getDataTableSelectedIds(target, datatable);

        let url = window.__getTargetUrl(target);
        let method = window.__getTargetMethod(target);
        let iframed = true;

        let data = {
            callertablename: tableId,
            ids: ids
        };

        window.openModalWithData (
            url,
            data,
            method,
            iframed
        )
    }

    window.___createAndSubmitForm = function(target, formParameters = {})
    {
        var table = window.__getTable(target);

        var tableId = $(table).data('realid');
        var datatable = table.DataTable();

        var filters = window.__getDTTableHeaderFilters(tableId);

        var ids = window.__getDataTableSelectedIds(target, datatable);

        var url = window.__getTargetUrl(target);

        var method = window.__getTargetMethod(target);


        if ($(target).data('formid'))
        {
            var form = document.getElementById($(target).data('formid')).cloneNode(true);

            $('#' + $(target).data('formid')).find('select').each(function ()
            {
                let selectName = $(this).attr('name');

                $(this).find(":selected").each(function ()
                {
                    var input = document.createElement("input");
                    input.type = "hidden";
                    input.name = selectName;
                    input.value = $(this).val();
                    form.appendChild(input);
                });
            });
        } else
            var form = document.createElement("form");

        // form.target = "modelpopupiframe";
        // form.target = "_blank";
        form.method = method;
        form.action = url;
        form.style.display = "none";

        for (const [key, value] of Object.entries(formParameters)) {
            form[key] = value;
        }

        for (var key in ids)
        {
            var input = document.createElement("input");
            input.type = "hidden";
            input.name = "ids[]";
            input.value = ids[key];
            form.appendChild(input);
        }

        for (var key in filters)
        {
            var input = document.createElement("input");
            input.type = "hidden";
            input.name = "filters[" + key + "]";
            input.value = filters[key];
            form.appendChild(input);
        }

        var input = document.createElement("input");
        input.type = "hidden";
        input.name = "_token";

        input.value = window.csrfToken;
        form.appendChild(input);
        document.body.appendChild(form);

        form.submit();
        document.body.removeChild(form);
    }

    window.__submitDatatable = function (target)
    {
        return window.___createAndSubmitForm(target);
    };

    window.__redirectSubmit = function (target) {
        let formParameters = {
            target : "_blank"
        };

        return window.___createAndSubmitForm(target, formParameters);
    };

    window.postTableToUrl = function(tableId, url)
    {
        let datatable = $(tableId).DataTable();
        let ids = window.__getDataTableSelectedIds(null, datatable);
        let type = 'POST';

        let data = {
            ids: ids
        };

        var params = {
            target : datatable,
        };

        return window.__ibCallAjax(url, type, data, params);
    }

    window.reloadAjaxTable = function(tableId)
    {
        let table = $(tableId).DataTable();

        table.rows().deselect();
        window.reloadDatatable(table);
    }

    window.removePopup = function(popupId)
    {
        UIkit.util.on(popupId, 'hide', function () {
            setTimeout(function()
            {
                $(popupId).remove();
            }, 1000);
        });

        UIkit.modal($(popupId)).hide();
    }

    window.closeModal = function ()
    {
        const modalEl = document.getElementById('datatablepopup');
        if (! modalEl)
            return;

        try {
            const modal = UIkit.modal(modalEl);

            // chiusura corretta UIkit (trigger lifecycle)
            modal.hide();

            // distruggi DOPO hide (serve il tick)
            UIkit.util.on(modalEl, 'hidden', function () {
                modalEl.remove();

                // sicurezza extra
                document.body.classList.remove('uk-modal-page');
                document.body.style.overflow = '';
                document.body.style.paddingRight = '';
                document.documentElement.style.overflow = '';
            }, { once: true });

        } catch (e) {
            // fallback brutale ma sicuro
            modalEl.remove();
        }
    };

    window.closeLightbox = function () {
        jQuery('.uk-lightbox').hide();
        // jQuery('.uk-lightbox').remove();

        window.dispatchEvent(new CustomEvent('sis-lightboxClosed'));
    };

    window.__ibForceUnlockBodyScroll = function ()
    {
        const body = document.body;

        body.classList.remove('uk-modal-page');
        body.style.overflow = '';
        body.style.paddingRight = '';

        // sicurezza extra: UIkit a volte aggiunge inline
        document.documentElement.style.overflow = '';

        console.log('fattone');
    };

    window.openModalWithData = function (url, data) {
        var type = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : 'POST';
        var iframed = arguments.length > 3 && arguments[3] !== undefined ? arguments[3] : true;
        $('body').append('<div id="datatablepopup" uk-modal><div class="uk-modal-dialog uk-modal-body uk-width-1-1 uk-height-1-1"><h2 class="uk-modal-title"></h2><button class="uk-modal-close-default" type="button" uk-close></button><iframe id="modelpopupiframe" name="modelpopupiframe" class="uk-width-1-1 uk-height-1-1"></iframe></div></div>');
        UIkit.modal($('#datatablepopup')).show();
        var form = document.createElement("form");
        form.target = "modelpopupiframe";
        form.method = type;
        form.action = url;
        form.style.display = "none";


        for (var key in data) {
            var input = document.createElement("input");
            input.type = "hidden";
            input.name = key;
            input.value = data[key];
            form.appendChild(input);
        }

        for(var key in data['ids'])
        {
            var input = document.createElement("input");
            input.type = "hidden";
            input.name = "ids[]";
            input.value = data['ids'][key];
            form.appendChild(input);

        }

        if (iframed) {
            var input = document.createElement("input");
            input.type = "hidden";
            input.name = "iframed";
            input.value = true;
            form.appendChild(input);
        }


        var input = document.createElement("input");
        input.type = "hidden";
        input.name = "_token";

        input.value = window.csrfToken;
        form.appendChild(input);
        document.body.appendChild(form);

        form.submit();
        document.body.removeChild(form);
    };

    window.__getTR = function(target)
    {
        return $(target).parents('tr');
    };

    window.__getTD = function(target)
    {
        return $(target).parents('td');
    };

    window.__getCell = function(target)
    {
        let table = $(target).parents('table.datatable').DataTable();
        let td = window.__getTD(target);

        return table.cell(td);
    };

    window.__getTH = function(target)
    {
        var tdIndex = $(target).closest('td').index() + 1;

        if($(target).parents('.dt-scroll').length > 0)
            return $(target).parents('.dt-scroll').find('.dt-scroll-head thead tr.columns th:nth-child(' + tdIndex + ')');

        return $(target).parents('table.dataTable').find('thead tr.columns th:nth-child(' + tdIndex + ')');
    }

    function __addSpinner(target)
    {
        let td = window.__getTD(target);

        td.css('position', 'relative');
        td.append("<div class='ib-spin'><span uk-spinner='ratio: 0.5'></span></div>");
    }

    function __addSpinnerIcon(target)
    {
        target.prepend("<div uk-spinner></div>");
    }

    function __removeSpinner(target)
    {
        window.__getTD(target).find('div.ib-spin').remove();
    }

    function __isEnabled(params)
    {
        if(($(params.target).hasClass('disabled'))||($(params.target).is(':disabled')))
            return false;

        return true;
    }

    window.__isHeaderConfirmed = function(params)
    {
        let th = window.__getTH(params.target);


        var confirmMessage = th.data('confirm');

        if (typeof confirmMessage !== 'undefined')
            if(! confirm(confirmMessage))
                return false;

        return true;
    }

    function __isConfirmed(params)
    {
        var returnconfirm = $(params.target).data('returnconfirm');

        if (typeof returnconfirm !== 'undefined')
            if(! confirm(returnconfirm))
                return false;

        return true;
    }

    function __manageSpinner(params)
    {
        if($(params.target).hasClass('spin') == true)
            __addSpinner(params.target);

        if($(params.target).hasClass('spinicon') == true)
            __addSpinnerIcon(params.target);
    }

    function __manageSpinnerRemoval(params)
    {
        if($(params.target).hasClass('spin') == true)
            __removeSpinner(params.target);
    }

    function __ibAjaxIsBlob(value)
    {
        return (typeof Blob !== 'undefined') && (value instanceof Blob);
    }

    function __ibAjaxIsFileList(value)
    {
        return (typeof FileList !== 'undefined') && (value instanceof FileList);
    }

    function __ibAjaxDataContainsFile(value)
    {
        if (! value)
            return false;

        if (__ibAjaxIsBlob(value) || __ibAjaxIsFileList(value))
            return true;

        if (Array.isArray(value))
            return value.some(__ibAjaxDataContainsFile);

        if (typeof value === 'object')
            return Object.keys(value).some(function (key)
            {
                return __ibAjaxDataContainsFile(value[key]);
            });

        return false;
    }

    function __ibAppendFormDataValue(formData, key, value)
    {
        if (value === undefined)
            return;

        if (value === null)
        {
            formData.append(key, '');
            return;
        }

        if (__ibAjaxIsBlob(value))
        {
            formData.append(key, value, value.name || 'file');
            return;
        }

        if (__ibAjaxIsFileList(value))
        {
            for (let i = 0; i < value.length; i++)
                __ibAppendFormDataValue(formData, key + '[' + i + ']', value[i]);

            return;
        }

        if (Array.isArray(value))
        {
            value.forEach(function (item, index)
            {
                __ibAppendFormDataValue(formData, key + '[' + index + ']', item);
            });

            return;
        }

        if (typeof value === 'object')
        {
            Object.keys(value).forEach(function (childKey)
            {
                __ibAppendFormDataValue(formData, key + '[' + childKey + ']', value[childKey]);
            });

            return;
        }

        formData.append(key, value);
    }

    function __ibBuildFormData(data)
    {
        if ((typeof FormData !== 'undefined') && (data instanceof FormData))
            return data;

        const formData = new FormData();

        Object.keys(data || {}).forEach(function (key)
        {
            __ibAppendFormDataValue(formData, key, data[key]);
        });

        return formData;
    }

    function __getData(params)
    {
        // if($(params.target).data('dataattributes'))
        //     return collectDataAttributes(params.target);

        // if($(params.target).data('elements'))
        //     return collectDatas(params.target);

        return params.data;
    }

    function __getType(params)
    {
        if($(params.target).data('type'))
            return $(params.target).data('type');

        return 'POST';
    }

    window.__getTargetMethod = function(target)
    {
        if($(target).data('method'))
            return $(target).data('method');

        return 'POST';
    }

    function __getParametersMethod(parameters)
    {
        return window.__getTargetMethod(parameters.target);
    }

    function __getUrl(params)
    {
        if($(params.target).data('url'))
            return $(params.target).data('url');

        if($(params.target).attr('href'))
            return $(params.target).attr('href');

        alert('missing url for this element');
    }

    window.__getTargetUrl = function(target)
    {
        if($(target).data('url'))
            return $(target).data('url');

        if($(target).data('route'))
            return $(target).data('route');

        if($(target).attr('href'))
            return $(target).attr('href');

        alert('missing url for this element');
    }

    function __addMethodToData(data, params)
    {
        if($(params.target).data('method'))
            data._method = $(params.target).data('method');

        return data;
    }

    window.__checkResultGeneric = function(result, params)
    {
        var htmlTable = $(params.target).parents('table.datatable');
        if(htmlTable.length == 0)
            return ;

        var focused = $(':focus');
        let table = $(params.target).parents('table.datatable').DataTable();
        let td = $(params.target).parents('td');
        let cell = table.cell(td);
        const cellIndex = cell.index();

        cellData = cell.data();

        let fieldName = params.data.field;

        if(typeof cellData[0] == 'object')
            for (var index in cellData)
            {
                if(cellData[index][0] == result['model-id'])
                    cellData[index][1] = result[fieldName];
            }

        else
            cellData[1] = result[fieldName];

        cell.data(cellData).draw(false);

        td.addClass('updated');

        if (__isEditorSaveTarget($(params.target)) && cellIndex)
            __showEditorSavedFeedback(table, table.row(cellIndex.row), cellIndex.column);

        $(focused).focus();
    }

    window.__getDataTableByClass = function (classname)
    {
        let table = $('.' + classname).first();

        let tableId = $(table).data('realid');

        return $('#' + tableId).DataTable();
    }

    window.__getDataTable = function(target)
    {
        if(target instanceof $.fn.dataTable.Api)
            return target;

        let tableId;

        if($(target).data('tableid'))
            tableId = $(target).data('tableid');

        else
            tableId = $(target).parents('table.datatable').data('realid');

        //this is because some elements contains # in the parameter string
        tableId = tableId.replace(/\b\#\w+/g, '');

        return $('#' + tableId).DataTable();
    }

    window.__getTableByCell = function(cell)
    {
        tableId = $(cell).parents('table').data('realid');
        tableId = tableId.replace(/\b\#\w+/g, '');
        return $('#' + tableId);
    }

    window.__getTable = function(target)
    {
        let tableId;

        if($(target).data('tableid'))
            tableId = $(target).data('tableid');

        else
            tableId = $(target).parents('table.datatable').data('realid');

        tableId = tableId.replace(/\b\#\w+/g, '');

        return $('#' + tableId);
    }

    window.__checkResultToggle = function (result, params) {

        if(! $(params.target).hasClass('ib-toggle'))
            return ;

        var table = $(params.target).parents('table.datatable').DataTable();
        var td = $(params.target).parents('td');
        var cell = table.cell(td);
        cellData = cell.data();
        var fieldName = params.data.field;
        if (_typeof(cellData[0]) == 'object') for (var index in cellData) {
            if (cellData[index][0] == result['model-id']) cellData[index][1] = result.value;
        } else cellData[1] = result.value;
        cell.data(cellData).draw(false);

        return true;
    };

    window.___reloadTable = function (table) {
        table.rows().deselect();
        // An explicit reloadTable response is authoritative: editor focus
        // locks must never defer it.
        window.reloadDatatable(table, { force: true });
        return true;
    };

    window.__reloadTable = function (params) {
        var table = window.__getDataTable(params.target);

        return window.___reloadTable(table);
    };

    window.ibDtCollectSelectedRowIds = function (dt) {
        const ids = [];

        if (! dt || typeof dt.rows !== 'function')
            return ids;

        dt.rows({ selected: true }).every(function () {
            const rowId = window.ibDtGetRowIdFromRowIndex(dt, this.index());

            if (rowId)
                ids.push(rowId);
        });

        return ids;
    };

    window.ibDtGetRowIdFromRowIndex = function (dt, rowIdx) {
        try {
            const node = dt.row(rowIdx).node();

            if (node) {
                const id = (node.getAttribute('id') || '').trim();

                if (id)
                    return id;
            }

            const data = dt.row(rowIdx).data();
            const rowIdSetting = dt.settings()[0].rowId;

            if (rowIdSetting != null && data != null) {
                if (typeof rowIdSetting === 'number' && Array.isArray(data) && data[rowIdSetting] != null)
                    return String(data[rowIdSetting]);

                if (typeof rowIdSetting === 'string' && data[rowIdSetting] != null)
                    return String(data[rowIdSetting]);
            }

            if (Array.isArray(data) && data[0] != null)
                return String(data[0]);
        } catch (err) {}

        return null;
    };

    window.ibDtRestoreRowSelection = function (dt, rowIds) {
        if (! dt || ! rowIds || ! rowIds.length)
            return;

        dt.rows().deselect();

        rowIds.forEach(function (id) {
            try {
                const row = dt.row('#' + id);

                if (row.any())
                    row.select();
            } catch (err) {}
        });
    };

    function ibDtDataValuesAreEqual(firstValue, secondValue) {
        if (firstValue === secondValue)
            return true;

        try {
            return JSON.stringify(firstValue) === JSON.stringify(secondValue);
        } catch (error) {
            return false;
        }
    }

    function ibDtGetDataValue(data, dataSource) {
        if (data === undefined || dataSource === null || typeof dataSource === 'function')
            return undefined;

        if (typeof dataSource === 'number')
            return data[dataSource];

        return String(dataSource).split('.').reduce(function (value, key) {
            return value === undefined || value === null ? undefined : value[key];
        }, data);
    }

    function ibDtGetChangedColumnIndexes(table, previousData, nextData) {
        return table.columns().indexes().toArray().filter(function (columnIndex) {
            const dataSource = table.column(columnIndex).dataSrc();
            const previousValue = ibDtGetDataValue(previousData, dataSource);
            const nextValue = ibDtGetDataValue(nextData, dataSource);

            return ! ibDtDataValuesAreEqual(previousValue, nextValue);
        });
    }

    window.reloadTableRows = function(tableId, rowIds, preserveSelectionIds, onRowsReloaded)
    {
        if(tableId != '#')
            var table = $(tableId).DataTable();
        else
            var table = $('.datatable').DataTable();

        var url = table.ajax.url();

        let rowIdIndex = table.settings()[0].rowId;

        $.ajax({
            dataType: "json",
            url: url,
            data: {
                ibeditor: true,
                rowIds: rowIds
            },
            success: function success(response)
            {
                const reloadedRows = [];

                response.data.forEach(function (value)
                {
                    let rowId = value[rowIdIndex];
                    const row = table.row("#" + rowId);
                    const changedColumnIndexes = ibDtGetChangedColumnIndexes(table, row.data(), value);

                    row.data(value).invalidate();
                    reloadedRows.push({ rowId: rowId, changedColumnIndexes: changedColumnIndexes });
                });

                if (preserveSelectionIds && preserveSelectionIds.length)
                    window.ibDtRestoreRowSelection(table, preserveSelectionIds);
                else
                    table.rows().deselect();

                table.draw(false);

                if (typeof onRowsReloaded === 'function')
                    onRowsReloaded(table, reloadedRows);
            },
            error: function error(response)
            {
                console.log(response);
                alert('ricaricare la pagina');
                return false; // location.reload();
            }
        });

        return true;

    }

    // A row refresh replaces its rendered cells.  Do not let a response from
    // an earlier editor save replace inputs while another editor save (or a
    // new local change) is still in progress.
    window.__ibDtPendingEditorSaves = window.__ibDtPendingEditorSaves || {};
    window.__ibDtQueuedRowRefreshes = window.__ibDtQueuedRowRefreshes || {};
    window.__ibDtFocusedEditors = window.__ibDtFocusedEditors || {};
    window.__ibDtEditorFocusHoldUntil = window.__ibDtEditorFocusHoldUntil || {};
    window.__ibDtEditorFocusHoldMs = 500;

    window.__ibTrackDtEditorFocus = function(target)
    {
        const tableDomId = $(target).closest('table').attr('id');

        if (tableDomId)
        {
            window.__ibDtFocusedEditors[tableDomId] = target;
            delete window.__ibDtEditorFocusHoldUntil[tableDomId];
        }
    };

    window.__ibReleaseDtEditorFocus = function(target)
    {
        const tableDomId = $(target).closest('table').attr('id');

        if (! tableDomId)
            return;

        // Keep the refresh lock briefly after leaving a field. This closes
        // the gap between blur and focusin when the user moves to the next
        // cell and the prior save has an unusually fast response.
        window.__ibDtEditorFocusHoldUntil[tableDomId] = Date.now() + window.__ibDtEditorFocusHoldMs;

        // focusout fires before focusin when moving to another editor. Wait
        // one turn so the new active editor can keep the table locked.
        setTimeout(function()
        {
            if (window.__ibDtFocusedEditors[tableDomId] !== target)
                return;

            delete window.__ibDtFocusedEditors[tableDomId];
        }, 0);
    };

    // Il container select2 sta dentro la cella del select che sostituisce: e'
    // lui a ricevere il focus quando il campo e' un editor.select con select2.
    window.__ibDtEditorFocusSelector = '.ib-editor-text, .ib-editor-select, .ib-editor-color, .ib-editor-custom-value, table.datatable tbody .select2-container';

    $(document).on('focusin', window.__ibDtEditorFocusSelector, function()
    {
        window.__ibTrackDtEditorFocus(this);
    });

    $(document).on('focusout', window.__ibDtEditorFocusSelector, function()
    {
        window.__ibReleaseDtEditorFocus(this);
    });

    window.__ibGetDtEditorSaveTableId = function(params)
    {
        return params && params.target
            ? $(params.target).closest('table').attr('id')
            : null;
    };

    window.__ibBeginDtEditorSave = function(params)
    {
        if (! params || ! params.deferRowRefresh)
            return;

        if (! params.dtEditorCellSaveTracked && typeof window.ibDtBeginEditorCellSave === 'function')
            params.dtEditorCellSaveTracked = window.ibDtBeginEditorCellSave(params.target);

        const tableDomId = window.__ibGetDtEditorSaveTableId(params);
        if (! tableDomId || params.dtEditorSaveTracked)
            return;

        params.dtEditorSaveTracked = true;
        params.dtEditorSaveTableId = tableDomId;
        window.__ibDtPendingEditorSaves[tableDomId] = (window.__ibDtPendingEditorSaves[tableDomId] || 0) + 1;
    };

    window.__ibCompleteDtEditorSave = function(params)
    {
        if (! params)
            return;

        if (params.dtEditorCellSaveTracked && typeof window.ibDtCompleteEditorCellSave === 'function')
        {
            window.ibDtCompleteEditorCellSave(params.target);
            params.dtEditorCellSaveTracked = false;
        }

        if (! params.dtEditorSaveTracked)
            return;

        const tableDomId = params.dtEditorSaveTableId;
        params.dtEditorSaveTracked = false;

        if (! tableDomId)
            return;

        const pending = Math.max(0, (window.__ibDtPendingEditorSaves[tableDomId] || 0) - 1);

        if (pending)
            window.__ibDtPendingEditorSaves[tableDomId] = pending;
        else
            delete window.__ibDtPendingEditorSaves[tableDomId];
    };

    window.__ibShouldDeferRowRefresh = function(tableDomId)
    {
        if (! tableDomId)
            return false;

        const pending = window.__ibDtPendingEditorSaves[tableDomId] || 0;
        if (pending > 0)
            return true;

        const focusedEditor = window.__ibDtFocusedEditors[tableDomId];
        if (focusedEditor)
        {
            if (document.documentElement.contains(focusedEditor) && $(focusedEditor).is(':focus'))
                return true;

            delete window.__ibDtFocusedEditors[tableDomId];
        }

        const focusHoldUntil = window.__ibDtEditorFocusHoldUntil[tableDomId] || 0;
        if (focusHoldUntil > Date.now())
            return true;

        delete window.__ibDtEditorFocusHoldUntil[tableDomId];

        if (typeof window.__ibTableHasDirtyEditors === 'function')
            return window.__ibTableHasDirtyEditors(tableDomId);

        return $('#' + tableDomId).find('.editorchanged').length > 0;
    };

    window.__ibQueueRowRefresh = function(params, tableDomId, rowId)
    {
        const key = tableDomId + ':' + rowId;
        const queued = window.__ibDtQueuedRowRefreshes[key] || {};

        queued.params = params;

        if (! queued.timer)
        {
            queued.timer = setTimeout(function()
            {
                delete window.__ibDtQueuedRowRefreshes[key];
                window.__refreshRow(queued.params);
            }, 150);
        }

        window.__ibDtQueuedRowRefreshes[key] = queued;
    };

    function __getEditorSavedColumn(params, table)
    {
        if (! params || Object.prototype.hasOwnProperty.call(params, 'dtEditorSavedColumn'))
            return params ? params.dtEditorSavedColumn : null;

        const $target = $(params.target);

        if (! __isEditorSaveTarget($target))
        {
            params.dtEditorSavedColumn = null;
            return null;
        }

        const $cell = $target.closest('td');

        if (! $cell.length)
        {
            params.dtEditorSavedColumn = null;
            return null;
        }

        const cellIndex = table.cell($cell).index();

        params.dtEditorSavedColumn = cellIndex && typeof cellIndex.column === 'number'
            ? cellIndex.column
            : null;

        return params.dtEditorSavedColumn;
    }

    function __isEditorSaveTarget($target)
    {
        return $target.is('.ib-editor-text, .ib-editor-select, .ib-editor-color, .ib-editor-custom-value, .ib-editor-file-upload');
    }

    function __renderEditorSavedFeedback($cell)
    {
        if (! $cell || ! $cell.length)
            return;

        const configuredDuration = Number($cell.closest('table').data('editorSavedFeedbackDuration'));
        const duration = Number.isFinite(configuredDuration) ? configuredDuration : 1500;

        if (duration <= 0)
            return;

        $cell.css('position', 'relative');
        $cell.children('.ib-datatable-editor-saved-feedback').remove();

        const $feedback = $(
            '<span class="ib-datatable-editor-saved-feedback" role="status" aria-label="Salvato">' +
                '<i class="fa-solid fa-check" aria-hidden="true"></i>' +
            '</span>'
        ).css('animation-duration', duration + 'ms');

        $cell.append($feedback);

        window.setTimeout(function()
        {
            $feedback.remove();
        }, duration);
    }

    function __showEditorSavedFeedback(table, row, columnIndex)
    {
        if (typeof columnIndex !== 'number')
            return;

        const cell = table.cell(row.index(), columnIndex).node();

        __renderEditorSavedFeedback($(cell));
    }

    function __showEditorSavedFeedbackForTarget(target, params = null)
    {
        const $target = $(target);

        if (! __isEditorSaveTarget($target))
            return;

        __renderEditorSavedFeedback($target.closest('td'));

        if (params)
            params.editorSaveFeedbackShown = true;
    }

    function __showEditorRowRefreshedNotification(columnIndex)
    {
        // Row refreshes can also be triggered by generic actions. Show this
        // micro-feedback only for a successful inline-editor save.
        if (typeof columnIndex !== 'number')
            return;

        if (typeof window.addSuccessNotification === 'function')
            window.addSuccessNotification('Riga aggiornata', 0.7);
    }

    window.__refreshRow = function(params)
    {
        let table = window.__getDataTable(params.target);
        let row = window.__getTR(params.target);

        // Inline editors live inside a DataTables child row. The record to
        // refresh is its parent data row, which owns the actual row id.
        if ($(row).hasClass('ib-datatable-inline-edit-child'))
            row = $(row).prev();

        let rowId = ($(row).attr('id') || '').trim();

        if (!rowId)
        {
            console.warn('Unable to refresh inline edit row: DataTables row id not found.');
            window.__ibClearDtDirtyGuardSaving(params);
            return false;
        }

        const tableDomId = $(table.table().node()).attr('id');
        const savedColumn = __getEditorSavedColumn(params, table);
        const refreshKey = tableDomId + ':' + rowId;
        const refreshTargetRow = table.row("#" + rowId);
        const revisionSnapshot = typeof window.ibDtCaptureRowRevisionSnapshot === 'function'
            ? window.ibDtCaptureRowRevisionSnapshot(table, refreshTargetRow)
            : {};
        const patchOptions = params && params.refreshActiveTargetCell
            ? { refreshActiveTargetCell: true, target: params.target }
            : null;

        window.__ibDtRowRefreshVersions = window.__ibDtRowRefreshVersions || {};
        const refreshVersion = (window.__ibDtRowRefreshVersions[refreshKey] || 0) + 1;
        window.__ibDtRowRefreshVersions[refreshKey] = refreshVersion;

        let modelName = table.getDataAttribute('relation');

        let url = table.ajax.url();
        const $refreshSpinnerCell = $(params.target).closest('td');

        console.log(rowId);

        $.ajax({
            dataType: "json",
            url: url,
            data: {
                ibeditor: true,
                rowId: rowId,
                refreshRow: true,
                modelName: modelName
            },
            success: function(response)
            {
                // A slower response from an earlier save must not overwrite
                // fields already refreshed by a later one.
                if (window.__ibDtRowRefreshVersions[refreshKey] !== refreshVersion)
                    return;

                const refreshedRow = table.row("#" + rowId);

                if (! response || ! Array.isArray(response.data) || ! response.data.length)
                {
                    console.warn('Unable to refresh DataTables row: response contains no row data.');
                    window.__ibClearDtDirtyGuardSaving(params);
                    return;
                }

                let patchResult;

                if (params.forceFullRowDrawOnRefresh)
                {
                    // The normal incremental patch deliberately protects
                    // focused/dirty editors. Select changes are already
                    // committed, so restore the pre-patch behaviour for this
                    // request only and remove the cell spinner before its DOM
                    // node is replaced.
                    __manageSpinnerRemoval(params);
                    $(refreshedRow.node()).find('div.ib-spin').remove();
                    refreshedRow.data(response.data[0]).invalidate();
                    table.draw(false);

                    patchResult = {
                        fullRowDraw: true,
                        invalidatedCells: table.columns().indexes().toArray().length,
                        protectedCells: 0,
                        staleCells: 0,
                    };
                }
                else
                {
                    patchResult = typeof window.ibDtPatchRenderedRow === 'function'
                        ? window.ibDtPatchRenderedRow(table, refreshedRow, response.data[0], revisionSnapshot, patchOptions)
                        : false;
                }

                if (! patchResult)
                {
                    console.warn('Unable to refresh DataTables row without redrawing it.');
                    window.__ibClearDtDirtyGuardSaving(params);
                    return;
                }

                const $refreshedRowNode = $(refreshedRow.node());

                $refreshedRowNode.removeClass('editorcansave');

                const $inlineEditorRow = $refreshedRowNode.next('.ib-datatable-inline-edit-child');

                if (! $refreshedRowNode.find('.editorchanged').add($inlineEditorRow.find('.editorchanged')).length)
                    $refreshedRowNode.removeClass('editorchangedrow');

                const tableId = $(table.table().node()).data('realid');
                const optionsVar = window[tableId + 'options'];

                if (optionsVar && typeof optionsVar.createdRow === 'function') {
                    const row = table.row("#" + rowId);

                    optionsVar.createdRow(row.node(), row.data(), row.index());
                }

                if (! params.editorSaveFeedbackShown)
                    __showEditorSavedFeedback(table, refreshedRow, savedColumn);
                __showEditorRowRefreshedNotification(savedColumn);

                window.__ibClearDtDirtyGuardSaving(params);

            },
            error: function(response)
            {
                console.log(response);
                alert('ricaricare la pagina, la riga non ha effettuato refresh in autonomia');
                window.__ibClearDtDirtyGuardSaving(params);

                return false;
                // location.reload();
            },
            complete: function()
            {
                $refreshSpinnerCell.find('div.ib-spin').remove();
            }
        });

        // if (typeof window.activateAllCleave === 'function')
        //     window.activateAllCleave();

        return true;
    }

    window.__checkResultPopup = function(response, params)
    {
        if(response.ibaction == 'openPopup')
            return window.__openPopupOLDRIFARE(response, params);

    }

    window.__reloadAllTables = function(params)
    {
        let tables = $.fn.dataTable.tables();

        tables.forEach(function (table, index)
        {
            window.reloadDatatable($(table).DataTable());
        });

        return true;
    }


    window.__checkResultAction = function(response, params)
    {
        if(typeof response.ibaction === "undefined")
            return false;

        var table = window.__getDataTable(params.target);
        var row = window.__getTR(params.target);
        var rowId = $(row).attr('id');
        $(table.row("#" + rowId).node()).removeClass('editorcansave');
        $(table.row("#" + rowId).node()).removeClass('editorchangedrow');

        if(response.ibaction == 'reloadAllTables')
            return window.__reloadAllTables(params);

        if(response.action == 'refreshRow')
            return window.__refreshRow(params);

        if ((response.action == 'none')||(response.ibaction == 'none'))
            return true;

        if(response.action == 'reloadTable')
            return window.__reloadTable(params);

        if(response.ibaction == 'openPopup')
            return window.__openPopupOLDRIFARE(response, params);

        if(response.ibaction == 'redirect')
            return window.location.href(response.href);

        return false;
    }

    window.__openPopupOLDRIFARE = function (response, params)
    {
        let table = window.__getTable(params.target);
        let tableId = $(table).data('realid');

        window.openModalWithData(
            response.route,
            {
                callertablename: tableId,
                target: params.target
            },
            'GET'
        );
    }

    window.__manageRowsRemoving = function(response, params)
    {
        if(response.action == 'remove')
        {
            console.log('__manageRowsRemoving _ remove');
            let table = window.__getDataTable(params.target);
            let reload = false;

            response.ids.forEach(function(value)
            {
                if($(table.row("#" + value).node()).length == 0)
                    reload = true;

                $(table.row("#" + value).node()).fadeOut(
                    800, function()
                    {
                        table.row("#" + value).remove();
                    });
            });

            if(reload)
                window.reloadDatatable(table);

            else
                table.draw();

            return true;
        }

        if(response.action == 'removeRow')
        {
            console.log('__manageRowsRemoving _ removeRow');
            let table = window.__getDataTable(params.target);
            let row = $(params.target).parents('tr');

            $(row).fadeOut(
                800, function()
                {
                    table.row(row).remove();
                });
        }

        return false;
    }

    window.dtEditorRefreshingFieldList = [];

    /**
     * Etichetta per log: selettore + data-field dell'editor (se presente nel DOM).
     */
    window.__dtRefreshingFieldDebugLabel = function (selector, $els)
    {
        var label = String(selector);

        if ($els && $els.length)
        {
            var $df = $els.filter('[data-field]').first();
            if (!$df.length)
                $df = $els.find('[data-field]').first();

            var df = $df.length ? $df.attr('data-field') : null;

            if (df)
                label += ' — data-field: "' + df + '"';
        }

        return label;
    };

    /**
     * Fallback quando l'host non definisce window.getFieldValueFromEditor:
     * allinea originalvalue degli input/select editor al valore corrente (post-save).
     */
    if (typeof window.getFieldValueFromEditor !== 'function')
        window.getFieldValueFromEditor = function ($root)
        {
            var $set = $root.find('.ib-editor-text, .ib-editor-select, .ib-editor-color');

            if ($root.is('.ib-editor-text, .ib-editor-select, .ib-editor-color'))
                $set = $set.add($root);

            $set.each(function ()
            {
                if (typeof window.__ibSetEditorOriginalValue === 'function')
                    window.__ibSetEditorOriginalValue(this, $(this).val());
                else
                    $(this).data('originalvalue', $(this).val());
            });
        };

    /**
     * @deprecated Sospeso — usare dtRefreshFieldsListBatch.
     */
    window.__ibLegacyDtRefreshFieldsList = function ()
    {
        if (! Array.isArray(window.dtEditorRefreshingFieldList))
            return;

        window.dtEditorRefreshingFieldList.forEach(function (fieldIdentifier)
        {
            var $field;

            try
            {
                $field = $(fieldIdentifier);

                if ($field.length === 0)
                {
                    console.warn('[datatables dtRefreshFieldsList] Selettore senza elementi:', fieldIdentifier);
                    return;
                }

                if (typeof window.getFieldValueFromEditor !== 'function')
                {
                    console.error('[datatables dtRefreshFieldsList] getFieldValueFromEditor non è una funzione. Selettore:', fieldIdentifier);

                    return;
                }

                window.getFieldValueFromEditor($field);
            }
            catch (err)
            {
                var label = window.__dtRefreshingFieldDebugLabel(fieldIdentifier, $field);

                console.error('[datatables dtRefreshFieldsList] Eccezione sul campo:', label, err);
            }
        });
    };

    window.dtRefreshFieldsList = function ()
    {
        if (typeof window.dtRefreshFieldsListBatch === 'function')
            return window.dtRefreshFieldsListBatch();

        return window.__ibLegacyDtRefreshFieldsList();
    };

    /**
     * Refresh in throttling dei campi registrati a ogni draw delle tabelle.
     * Trailing throttle: la prima draw arma il timer, le successive nella
     * finestra vengono assorbite; la chiamata parte una sola volta a fine finestra.
     */
    window.__ibDtRefreshFieldsListOnDrawThrottleMs = 1000;

    window.__ibScheduleDtRefreshFieldsListOnDraw = function ()
    {
        if (! Array.isArray(window.dtEditorRefreshingFieldList) || ! window.dtEditorRefreshingFieldList.length)
            return;

        if (window.__ibDtRefreshFieldsListOnDrawTimer)
            return;

        window.__ibDtRefreshFieldsListOnDrawTimer = setTimeout(function ()
        {
            window.__ibDtRefreshFieldsListOnDrawTimer = null;

            window.dtRefreshFieldsList();
        }, window.__ibDtRefreshFieldsListOnDrawThrottleMs);
    };

    $(document).on('draw.dt', function ()
    {
        window.__ibScheduleDtRefreshFieldsListOnDraw();
    });

    window.__removeEditorSaveClasses = function(params)
    {
        var table = window.__getDataTable(params.target);
        var row = window.__getTR(params.target);
        var rowId = $(row).attr('id');

        $(table.row("#" + rowId).node()).removeClass('editorcansave');
        $(table.row("#" + rowId).node()).removeClass('editorchangedrow');
    }

    window.__ibSetDtDirtyGuardSaving = function(params)
    {
        if (! params || ! params.suppressDtDirtyGuard)
            return;

        const tableDomId = $(params.target).closest('table').attr('id');

        if (! tableDomId)
            return;

        params.dtDirtyGuardTableId = tableDomId;
        window.__ibDtSaving = window.__ibDtSaving || {};
        window.__ibDtSaving[tableDomId] = true;
    }

    window.__ibClearDtDirtyGuardSaving = function(params)
    {
        const tableDomId = params && params.dtDirtyGuardTableId;

        if (! tableDomId || ! window.__ibDtSaving)
            return;

        delete window.__ibDtSaving[tableDomId];
    }

    window.__ibCallAjax = function(url, type, data, params)
    {
        window.__ibBeginDtEditorSave(params);

        const isFormData = (typeof FormData !== 'undefined') && (data instanceof FormData);

        const ajaxOptions = {
                url     : url,
                type    : type,
                dataType: params.responseDataType || $(params.target).data('responseDataType') || 'json',
                data    : data,
                success : function(response)
                {
                    if (typeof params.onSuccess === 'function')
                    {
                        try
                        {
                            params.onSuccess(response, params);
                        }
                        finally
                        {
                            __manageSpinnerRemoval(params);
                        }

                        return;
                    }

                    // jQuery invokes success for every successful HTTP
                    // response, including 204 No Content. Normalise an empty
                    // body before inspecting action/ibaction below so fields
                    // configured to refresh their row do so for any 2xx.
                    if (! response || typeof response !== 'object')
                        response = {};

                    $(params.target).closest('.editorcansave').removeClass('.editorcansave');

                    window.dtRefreshFieldsList();

                    window.__removeEditorSaveClasses(params);

                    // Confirm every successful inline field save immediately.
                    // A row refresh can be deferred while the user edits other
                    // cells in the same row, so it must not gate this feedback.
                    __showEditorSavedFeedbackForTarget(params.target, params);

                    const mustReloadTable = params.reloadTableOnSuccess === true
                        || (typeof window.ibDtEditorResponseRequestsTableReload === 'function'
                            ? window.ibDtEditorResponseRequestsTableReload(response)
                            : (response.action === 'reloadTable' || response.ibaction === 'reloadTable'));

                    if (mustReloadTable)
                    {
                        // reloadTable is authoritative and must win over row
                        // refresh/default actions, even while the editor that
                        // triggered the save still owns focus.
                        __manageSpinnerRemoval(params);
                        window.__ibCompleteDtEditorSave(params);
                        window.__ibClearDtDirtyGuardSaving(params);

                        return window.__reloadTable(params);
                    }

                    const mayForceRowRefresh = params.forceRefreshRowOnSuccess
                        && (! response.action || response.action === 'none')
                        && (! response.ibaction || response.ibaction === 'none');

                    if (params.refreshRowOnSuccess
                        && ((! response.action && ! response.ibaction) || mayForceRowRefresh))
                        response.action = 'refreshRow';

                    if (response.action == 'refreshRow')
                    {
                        // The update itself has completed. A subsequent row
                        // refresh may be queued by the editor lock, but must
                        // not keep the field spinner visible in the meantime.
                        __manageSpinnerRemoval(params);
                        window.__ibCompleteDtEditorSave(params);
                        return window.__refreshRow(params);
                    }

                    if (response.action == 'reloadAllTables') return window.__reloadAllTables(params);
                    if (response.ibaction == 'redirect') return window.location.href(response.href);

                    __checkResultToggle(response, params);

                    if(! __checkResultAction(response, params))
                        if(! window.__manageRowsRemoving(response, params))
                            __checkResultGeneric(response, params);

                    // checkJavascript(response, params.target);
                    // checkRemoveElement(response, params.target);
                    // checkMessage(response);

                    // if(! newCheckTargetHtmlAppend(response, params.target))
                    //     checkTargetHtmlAppend(response, params.target);

                    // checkTargetHtml(response, params.target);

                    // if(! newCheckTargetHtml(response, params.target))
                    //     checkHtml(response, params.target);

                    // checkUrl(response, params.target);
                    // checkClass(response, params.target);
                    // checkIcon(response, params.target);
                    // checkDatas(response, params.target);
                    // checkRemoveClass(response, params.target);
                    // checkTooltip(response, params.target);
                    // checkNewselecttor(response, params.target);
                    // checkFinalJavascript(response, params.target);

                    __manageSpinnerRemoval(params);
                    __manageSuccessMessages(response);
                    window.__ibCompleteDtEditorSave(params);
                    window.__ibClearDtDirtyGuardSaving(params);
                },
                error: function(response)
                {
                    console.log(response);
                    __displayResponseErrors(response);
                    __manageSpinnerRemoval(params);
                    window.__ibCompleteDtEditorSave(params);
                    window.__ibClearDtDirtyGuardSaving(params);
                }
            };

        ajaxOptions.headers = window.ibGetDatatableBroadcastHeaders(params && params.target);

        if (isFormData)
        {
            ajaxOptions.processData = false;
            ajaxOptions.contentType = false;
        }

        $.ajax(ajaxOptions);

    }

    window.ibGetDatatableBroadcastHeaders = function(target)
    {
        const table = getBroadcastSourceTable(target);
        const browserTabId = typeof window.ibGetDatatableBrowserTabId === 'function'
            ? window.ibGetDatatableBrowserTabId()
            : null;

        if (! table || ! browserTabId)
            return {};

        return {
            'X-IB-Datatable-Browser-Tab-Id': browserTabId,
            'X-IB-Datatable-Table-Id': table.id,
        };
    };

    function getBroadcastSourceTable(target)
    {
        if (! target)
            return null;

        let $table = $(target).closest('table.datatable');

        if (! $table.length && $(target).data('tableid'))
            $table = $('#' + $(target).data('tableid'));

        if (! $table.length)
            return null;

        const table = $table.get(0);

        if (! table || ! table.id || ! table.getAttribute('data-model-broadcast-channel'))
            return null;

        return table;
    }

    window.ibGetThFromClickedCellContent = function(target)
    {
        let classes = $(target).parents('td').attr('class').split(' ')[0];
        let index = $(target).parents('td').index();
        let th = $(target).parents('table').find('thead tr').find('th:nth-child(' + (index + 1) + ')');

        if(! $(th).hasClass(classes))
        {
            window.addDangerNotification('La cella ' + index + ' cliccata ha la classe .' + classes + ' mentre la sua intestazione non presenta la stessa classe (' + $(th).attr('class') + '). Probabilmente ci sono dei problemi di indice tra colonna TD e colonna TH. Verificatre');
            return false;
        }

        return th;
    }

    window.ibCollectDtCellExtraData = function(target)
    {
        let th = window.ibGetThFromClickedCellContent(target);

        let extraData = $(th).data('ajaxextradata');

        if(extraData instanceof Array)
            extraData = Object.fromEntries(extraData);

        let targetData = $(target).data();

        if(targetData instanceof Array)
            targetData = Object.fromEntries(targetData);

        return jQuery.extend(extraData, targetData);
    }

    window.ibCallAjax = function(params)
    {
        params.e.preventDefault();


        // params.data.fieldExtraData = extraData;
        // params.data.fieldExtraData = window.ibCollectDtCellExtraData(params.target);

        if ($(params.target).data('sendAjaxPayload') !== false)
        {
            let th = window.__getTH($(params.target));
            params.data.fieldExtraData = th.data();
            params.data.fieldData = $(params.target).data();

            if (typeof window.ibDtEditorFieldRequestsTableReload === 'function'
                && window.ibDtEditorFieldRequestsTableReload(params.data.fieldExtraData))
            {
                params.reloadTableOnSuccess = true;
            }
        }

        if(! __isEnabled(params))
            return false;

        if(! __isConfirmed(params))
            return false;

        if(! __isHeaderConfirmed(params))
            return false;

        __manageSpinner(params);

        var type = __getType(params);
        var url = __getUrl(params);
        let data = __getData(params);

        data = __addMethodToData(data, params);

        if (__ibAjaxDataContainsFile(data))
            data = __ibBuildFormData(data);

        return window.__ibCallAjax(url, type, data, params);
    }

    function __manageSuccessMessages(response)
    {
        if(typeof response.message !== 'undefined')
            window.addSuccessNotification(response.message);

        // else
        //     window.addSuccessNotification('elemento aggiornato');
    }

    window.__displayResponseErrors = function(jsonResponse)
    {
        if(typeof jsonResponse.exception !== 'undefined')
            alert(jsonResponse.message);

        if(typeof jsonResponse.errors !== 'undefined')
            for (var field in jsonResponse.errors)
            {
                let errorMessage = field;

                for (var error in jsonResponse.errors[field])
                    errorMessage += ' ' + jsonResponse.errors[field][error];

                window.addDangerNotification(errorMessage);
            }

        if (typeof jsonResponse.responseJSON !== 'undefined')
        {
            let response = jsonResponse.responseJSON;

            if (typeof response.message !== 'undefined')
                alert(response.message);
        }
    }

    window.__getIdColumnIndex = function(target, table)
    {
        //never used as override by the moment
        if($(target).data('idcolumn'))
            return $(target).data('idcolumn');

        return table.init().rowId;
    }
});
